import{_ as s,C as r,o as i,c as l,a3 as t,E as n}from"./chunks/framework.bGC-1KKp.js";const m=JSON.parse('{"title":"Lab 02 — Radiographie du mandat","description":"","frontmatter":{"title":"Lab 02 — Radiographie du mandat","aside":false},"headers":[],"relativePath":"labs/lab02-radiographie-mandat.md","filePath":"labs/lab02-radiographie-mandat.md"}'),o={name:"labs/lab02-radiographie-mandat.md"};function u(c,e,d,p,h,g){const a=r("MatriceRisques");return i(),l("div",null,[e[0]||(e[0]=t('<h1 id="lab-02-—-radiographie-du-mandat" tabindex="-1">Lab 02 — Radiographie du mandat <a class="header-anchor" href="#lab-02-—-radiographie-du-mandat" aria-label="Permalink to &quot;Lab 02 — Radiographie du mandat&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Objectifs du laboratoire</strong><br><ul class="list-disc pl-5"><li>Relever <strong>toutes</strong> les contraintes d&#39;un mandat réel et les classer.</li><li>Traduire les demandes du client en exigences fonctionnelles et non fonctionnelles.</li><li>Évaluer des risques selon leurs chances d&#39;arriver et leurs conséquences, et proposer des mesures.</li><li>Dresser la liste des problèmes techniques à prévoir.</li></ul></div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Modalités</strong><br><ul class="list-disc pl-5"><li>Avec <strong>votre équipe de la session</strong> (2 ou 3 personnes).</li><li>Durée : environ 55 minutes, puis correction commentée en grand groupe.</li><li>Remise : la fiche remplie, déposée dans l&#39;<strong>équipe Teams du cours</strong>. Ce travail est <strong>formatif</strong> (non noté)… mais c&#39;est la base de votre <strong>évaluation 1</strong>. Gardez-le précieusement.</li></ul></div><hr><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><p>Studio Web FC, c&#39;est vous. Aventure Saint-Maurice vous a confié son projet et vous devez produire un rapport de faisabilité. Avant de penser à une seule solution, un analyste fait la <strong>radiographie</strong> du mandat : il relève tout ce qui limite le projet, tout ce qu&#39;il doit faire et tout ce qui pourrait mal tourner.</p><blockquote><p><strong>Règle d&#39;or du lab :</strong> on ne propose <strong>aucune solution</strong> aujourd&#39;hui. Pas de « on prendrait WordPress », pas de « il faudrait Shopify ». On décrit la situation. Les choix viendront plus tard.</p></blockquote><hr><h2 id="preparation" tabindex="-1">Préparation (5 min) <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Préparation (5 min) {#preparation}&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Ouvrir le <a href="./../mandat/" target="_blank">mandat Aventure Saint-Maurice</a> dans un onglet</span></label></li><li><label><input type="checkbox"><span class="check-text"><a href="./../fiches/lab02-fiche-radiographie.docx" download>Télécharger la fiche de radiographie (Word)</a> et la placer dans le dossier partagé de l&#39;équipe</span></label></li><li><label><input type="checkbox"><span class="check-text">Se répartir la lecture : une personne par document (courriel, notes, chiffres), puis chacun résume le sien aux autres en deux minutes</span></label></li></ul><hr><h2 id="partie-1" tabindex="-1">Partie 1 — Les contraintes (20 min) <a class="header-anchor" href="#partie-1" aria-label="Permalink to &quot;Partie 1 — Les contraintes (20 min) {#partie-1}&quot;">​</a></h2><p>Relevez <strong>au moins 15 contraintes</strong> dans le mandat. Pour chacune, remplissez une ligne du tableau de la fiche.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Colonne</th><th style="text-align:left;">Ce qu&#39;on y écrit</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Contrainte</strong></td><td style="text-align:left;">La contrainte, dans vos mots, en une phrase</td></tr><tr><td style="text-align:left;"><strong>Source</strong></td><td style="text-align:left;">Le document et un court extrait qui la prouve</td></tr><tr><td style="text-align:left;"><strong>Sorte</strong></td><td style="text-align:left;"><strong>T</strong> (technique), <strong>O</strong> (organisationnelle) ou <strong>R</strong> (ressources)</td></tr><tr><td style="text-align:left;"><strong>Élément</strong></td><td style="text-align:left;">Budget, délai, personnel, technologie ou loi</td></tr></tbody></table><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Pour ne rien oublier, cherchez dans chaque catégorie</strong><br><ul class="list-disc pl-5"><li><strong>Budget :</strong> construction, coûts annuels, commissions, subvention.</li><li><strong>Délai :</strong> dates fermes, dates souhaitées, saisons.</li><li><strong>Personnel :</strong> qui construit, qui entretient, compétences, disponibilité selon la saison.</li><li><strong>Technologie :</strong> les outils qui existent déjà, les comptes, les accès, le réseau sur place.</li><li><strong>Lois et règles :</strong> renseignements personnels, langue, accessibilité, assurance.</li></ul></div><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Une contrainte n&#39;est pas un souhait</strong><br> « Le client veut une vidéo plein écran » est un souhait. « Le site doit bien s&#39;afficher avec un réseau cellulaire faible » est une contrainte. Si vous hésitez, demandez-vous : <em>est-ce que ça limite nos choix ?</em></div><hr><h2 id="partie-2" tabindex="-1">Partie 2 — Les exigences (10 min) <a class="header-anchor" href="#partie-2" aria-label="Permalink to &quot;Partie 2 — Les exigences (10 min) {#partie-2}&quot;">​</a></h2><h3 id="ce-que-le-site-doit-faire" tabindex="-1">Ce que le site doit faire <a class="header-anchor" href="#ce-que-le-site-doit-faire" aria-label="Permalink to &quot;Ce que le site doit faire&quot;">​</a></h3><p>Dressez la liste d&#39;au moins <strong>8 exigences fonctionnelles</strong>. Écrivez-les sous la forme : <strong>« [Qui] peut [faire quoi]. »</strong></p><blockquote><p><em>Exemple :</em> Un client peut voir les places qui restent pour un départ de via ferrata.</p></blockquote><p>Pensez à tous les utilisateurs : le client, le parent, le responsable d&#39;un groupe, Karine à l&#39;accueil, les guides, Mélanie.</p><h3 id="comment-il-doit-le-faire" tabindex="-1">Comment il doit le faire <a class="header-anchor" href="#comment-il-doit-le-faire" aria-label="Permalink to &quot;Comment il doit le faire&quot;">​</a></h3><p>Pour <strong>chacune des cinq catégories</strong> vues en classe, écrivez <strong>une exigence précise</strong> tirée du mandat.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Catégorie</th><th style="text-align:left;">Votre exigence</th></tr></thead><tbody><tr><td style="text-align:left;">Vitesse</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Sécurité</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Accessibilité</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Loi 25 et langue</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Navigateurs et appareils</td><td style="text-align:left;"></td></tr></tbody></table><hr><h2 id="partie-3" tabindex="-1">Partie 3 — Les risques (15 min) <a class="header-anchor" href="#partie-3" aria-label="Permalink to &quot;Partie 3 — Les risques (15 min) {#partie-3}&quot;">​</a></h2><h3 id="_1-placer-les-risques" tabindex="-1">1. Placer les risques <a class="header-anchor" href="#_1-placer-les-risques" aria-label="Permalink to &quot;1. Placer les risques&quot;">​</a></h3><p>Voici dix risques du projet. Placez chacun dans la matrice selon <strong>ses chances d&#39;arriver</strong> et <strong>ses conséquences</strong>. Discutez en équipe : vous devez être capables de justifier chaque placement.</p>',29)),n(a),e[1]||(e[1]=t('<h3 id="_2-completer" tabindex="-1">2. Compléter <a class="header-anchor" href="#_2-completer" aria-label="Permalink to &quot;2. Compléter&quot;">​</a></h3><p>Dans la fiche :</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Reportez la position de chaque risque (p. ex. R3 : moyenne / graves)</span></label></li><li><label><input type="checkbox"><span class="check-text">Ajoutez <strong>deux risques</strong> que la liste a oubliés : un technique et un organisationnel</span></label></li><li><label><input type="checkbox"><span class="check-text">Pour chaque risque de la <strong>zone rouge</strong>, proposez une <strong>mesure</strong> qui le réduit</span></label></li></ul><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Une mesure n&#39;est pas une solution technique</strong><br> « Fixer une date limite pour la remise des photos » est une mesure. « Prendre FareHarbor » est une solution : gardez-la pour l&#39;évaluation 2. </div><hr><h2 id="partie-4" tabindex="-1">Partie 4 — Les problèmes techniques à prévoir (10 min) <a class="header-anchor" href="#partie-4" aria-label="Permalink to &quot;Partie 4 — Les problèmes techniques à prévoir (10 min) {#partie-4}&quot;">​</a></h2><p>Choisissez les <strong>cinq problèmes techniques</strong> qui vous inquiètent le plus. Pour chacun :</p><table tabindex="0"><thead><tr><th style="text-align:left;">Problème</th><th style="text-align:left;">Pourquoi c&#39;est un problème</th><th style="text-align:left;">Ce qu&#39;il faut vérifier ou demander</th></tr></thead><tbody><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr></tbody></table><p>Vous pouvez vous inspirer de l&#39;activité des cinq phrases, mais trouvez-en <strong>au moins deux autres</strong>.</p><hr><h2 id="defi-bonus" tabindex="-1">Défi bonus <a class="header-anchor" href="#defi-bonus" aria-label="Permalink to &quot;Défi bonus&quot;">​</a></h2><p>Mélanie a écrit : « Est-ce que c&#39;est faisable ? » Rédigez la réponse que vous lui enverriez <strong>ce soir</strong>, en <strong>cinq lignes maximum</strong>, sans aucun mot technique. Vous ne pouvez pas encore dire oui ou non : que lui dites-vous ?</p><hr><h2 id="remise" tabindex="-1">Remise <a class="header-anchor" href="#remise" aria-label="Permalink to &quot;Remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Au moins 15 contraintes, chacune avec sa source, sa sorte et son élément</span></label></li><li><label><input type="checkbox"><span class="check-text">Au moins 8 exigences fonctionnelles et une exigence par catégorie non fonctionnelle</span></label></li><li><label><input type="checkbox"><span class="check-text">Les 10 risques placés, 2 risques ajoutés, une mesure pour chaque risque de la zone rouge</span></label></li><li><label><input type="checkbox"><span class="check-text">Cinq problèmes techniques à prévoir</span></label></li><li><label><input type="checkbox"><span class="check-text">Le fichier est nommé <code>lab02-equipeN-nom1-nom2.docx</code> et déposé dans l&#39;équipe Teams du cours</span></label></li></ul><hr><h2 id="correction-commentee" tabindex="-1">Correction commentée <a class="header-anchor" href="#correction-commentee" aria-label="Permalink to &quot;Correction commentée&quot;">​</a></h2><p>En grand groupe, on bâtit ensemble :</p><ul><li>la liste complète des contraintes, chaque équipe ajoutant celles que les autres n&#39;ont pas trouvées ;</li><li>la matrice des risques de la classe : on compare les placements et on discute des désaccords ;</li><li>les trois problèmes techniques qui reviennent le plus souvent.</li></ul><p>Corrigez votre fiche au fil de la discussion, <strong>dans une autre couleur</strong>. Elle vous servira pour l&#39;évaluation 1.</p>',20))])}const q=s(o,[["render",u]]);export{m as __pageData,q as default};
